function normalize(obj){if(!obj||obj.schema!==3||!Array.isArray(obj.tasks)||!Array.isArray(obj.notes)||!Array.isArray(obj.transactions))throw Error('Unrecognized HOE data');const base=newVault();const result={...base,...obj};for(let [field,v] of Object.entries(base))if(Array.isArray(v))result[field]=Array.isArray(obj[field])?obj[field].filter(x=>x&&typeof x==='object'):v;result.settings={...base.settings,...obj.settings};if(!Array.isArray(result.categories))result.categories=base.categories;result.categories=[...new Set(result.categories.filter(x=>typeof x==='string'&&x.trim()))];if(!result.categories.length)result.categories=['Personal'];if(!Array.isArray(result.radarItems)||!result.radarItems.length)result.radarItems=initialRadar.map(x=>({...x}));if(!result.radarDays||typeof result.radarDays!=='object'||Array.isArray(result.radarDays))result.radarDays={};if(!Array.isArray(result.events))result.events=[];if(!Array.isArray(result.dailyLogs))result.dailyLogs=[];
 // Earlier separate journal entries are kept, and also made visible in unified Notes exactly once.
 if(!result.mergedJournalV5){for(const j of result.journal||[]){if(!j.isDemo&&!result.notes.some(n=>n.id===j.id))result.notes.push({id:j.id||id(),title:j.title||'Reflection',body:j.body||j.text||'',created:j.date||localDay(),updated:j.date||localDay(),pinned:false})}result.mergedJournalV5=true}
 return result}
function migrateV2(old){let out=newVault();out.legacySnapshot=old;for(let t of old.tasks||[])if(!t.isDemo)out.tasks.push({...t,id:t.id||id(),priority:Number(t.priority)||1,category:t.category||'Personal',due:t.due||t.date||''});for(let n of old.notes||[])if(!n.isDemo)out.notes.push({...n,id:n.id||id(),body:n.body||''});for(let v of old.events||[])if(!v.isDemo)out.events.push({...v,id:v.id||id(),duration:v.duration||30});for(let j of old.journal||[])if(!j.isDemo)out.notes.push({id:j.id||id(),title:j.title||'Reflection',body:j.body||j.text||'',created:j.date||localDay()});for(let x of old.money?.transactions||[])if(!x.isDemo)out.transactions.push({...x,id:x.id||id(),type:x.type==='income'?'In':'Out'});out.mergedJournalV5=true;return out}
async function persist(){if(!data||!key||!stored)return;const snapshot=structuredClone(data),secret=key,salt=stored.salt,iterations=stored.iterations||ITER;let job=persistQueue.then(async()=>{const sealed=await encrypt(snapshot,secret,salt,iterations);await writeVault(sealed);stored=sealed;lastSave=Date.now()});persistQueue=job.catch(err=>{console.error('Save failure',err);message('Could not save. Export an encrypted backup before closing.')});return job}
function logActivity(label){data.history.unshift({id:id(),date:new Date().toISOString(),action:label});data.history=data.history.slice(0,700)}
function commit(label){if(label)logActivity(label);return persist()}
function setTheme(){document.documentElement.dataset.theme=data?.settings.theme==='light'?'light':'dark'}
function lock(){if(!data)return;data=null;key=null;layer.innerHTML='';clearInterval(clock);clock=null;renderAuth('unlock')}
async function startup(){try{if(!crypto?.subtle||!indexedDB)throw Error('Web Crypto or IndexedDB unavailable');db=await openDb();stored=await readVault();try{pendingLegacy=!!localStorage.getItem(LEGACY)}catch{}renderAuth(stored?'unlock':'setup')}catch(err){header.innerHTML='';nav.innerHTML='';view.innerHTML=`<div class="auth"><h1>Private storage unavailable</h1><p class="subtle">Use HOE over HTTPS in a recent browser with IndexedDB enabled. No existing records were deleted.</p><p class="fine danger-text">${esc(err.message)}</p></div>`}}
function renderAuth(kind){header.innerHTML='';nav.innerHTML='';const setup=kind==='setup';view.innerHTML=`<div class="auth"><div class="brand">HOE</div><div class="brand-desc">HEAVEN ON EARTH</div><h1>${setup?'Your space. Your key.':'Welcome back.'}</h1><p class="section-sub">${setup?'Create a private vault on this device.':'Unlock your encrypted records.'}</p>${setup&&pendingLegacy?'<div class="panel" style="margin-bottom:18px">Earlier HOE records were found. They will be encrypted and copied into this vault. Your earlier data will not be cleared until that succeeds.</div>':''}<form id="auth-form"><div class="field"><label for="pass">Passphrase</label><input id="pass" class="input" type="password" autocomplete="${setup?'new-password':'current-password'}" minlength="${setup?10:1}" required></div>${setup?'<div class="field"><label for="pass-repeat">Confirm passphrase</label><input id="pass-repeat" class="input" type="password" autocomplete="new-password" minlength="10" required></div>':''}<button class="button primary block" type="submit">${setup?'Create encrypted vault':'Unlock HOE'}</button></form><div id="auth-error" class="danger-text fine" role="alert"></div><p class="auth-note">Your records are encrypted locally with AES-256-GCM. HOE has no recovery server. Keep your passphrase and encrypted backup safe.</p></div>`;
 $('#auth-form').onsubmit=async ev=>{ev.preventDefault();const pass=$('#pass').value,button=ev.target.querySelector('button[type="submit"]');$('#auth-error').textContent='';button.disabled=true;try{if(setup){if(pass.length<10)throw Error('Use a passphrase of at least 10 characters.');if(pass!==$('#pass-repeat').value)throw Error('Passphrases do not match.');const salt=[...crypto.getRandomValues(new Uint8Array(16))];key=await derive(pass,salt);let old;try{old=JSON.parse(localStorage.getItem(LEGACY)||'null')}catch{}data=old?.version===2?migrateV2(old):newVault();stored={salt,iterations:ITER};await persist();if(old?.version===2){try{localStorage.removeItem(LEGACY)}catch{}}}else{key=await derive(pass,stored.salt,stored.iterations||ITER);data=normalize(await decrypt(stored,key));await persist()}lastActive=Date.now();ui.route='';ui.page='today';ui.mode='life';ui.date=localDay();setTheme();render();message('Your private space is ready.')}catch(err){key=null;data=null;$('#auth-error').textContent=err.name==='OperationError'?'Incorrect passphrase or damaged vault. Your records have not changed.':err.message}finally{if(button.isConnected)button.disabled=false}}}
function button(label,action,primary=false,extra=''){return `<button type="button" class="button ${primary?'primary':''} ${extra}" data-act="${esc(action)}">${label}</button>`}
function title(name,description='',action='',actionText=''){return `<div style="display:flex;align-items:flex-start;gap:12px;justify-content:space-between"><div style="min-width:0"><h1>${esc(name)}</h1>${description?`<p class="section-sub">${esc(description)}</p>`:''}</div>${action?`<button class="icon-button" data-act="${esc(action)}" aria-label="${esc(actionText)}">${ic('plus',23)}</button>`:''}</div>`}
function sect(name,action='',label='View all'){return `<div class="section-heading"><h2>${esc(name)}</h2>${action?`<button data-act="${esc(action)}">${esc(label)} ${ic('next',13)}</button>`:''}</div>`}
function row(name,desc='',action='',end='',ico=''){return `<button type="button" class="row" data-act="${esc(action)}">${ico?ic(ico,19):''}<span class="row-main"><span class="row-title">${esc(name)}</span>${desc?`<span class="row-desc" style="display:block">${esc(desc)}</span>`:''}</span>${end?`<span class="row-end">${esc(end)}</span>`:''}${ic('next',15)}</button>`}
function chips(items,selected,prefix){return `<div class="chips">${items.map(x=>`<button class="chip ${selected===x?'on':''}" data-act="${prefix}:${encodeURIComponent(x)}">${esc(x)}</button>`).join('')}</div>`}
function segment(items,current,prefix){return `<div class="segment">${items.map(([k,v])=>`<button class="${k===current?'selected':''}" data-act="${prefix}:${k}">${esc(v)}</button>`).join('')}</div>`}
function check(d){return `<span class="checkbox-svg ${d?'on':''}">${d?ic('check',14):''}</span>`}
function donut(count,total,large=false){let percent=total?Math.round(count/total*100):0;return `<div class="donut ${large?'large':''}" style="--percent:${percent}%"><div class="donut-inner"><b>${count}/${total}</b><small>${large?'Completed':'Today'}</small></div></div>`}
function field(name,label,value='',type='text',required=false){return `<div class="field"><label for="f-${esc(name)}">${esc(label)}</label><input id="f-${esc(name)}" class="input" name="${esc(name)}" type="${esc(type)}" value="${esc(value)}" ${required?'required':''}></div>`}
function area(name,label,value='',rows=3){return `<div class="field"><label for="f-${esc(name)}">${esc(label)}</label><textarea class="input" id="f-${esc(name)}" name="${esc(name)}" rows="${rows}">${esc(value)}</textarea></div>`}
function select(name,label,options,value){return `<div class="field"><label for="f-${esc(name)}">${esc(label)}</label><select class="input" id="f-${esc(name)}" name="${esc(name)}">${options.map(opt=>{let [v,l]=Array.isArray(opt)?opt:[opt,opt];return `<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(l)}</option>`}).join('')}</select></div>`}
function sheet(name,content,onSubmit=null,submitText='Save'){layer.innerHTML=`<div class="shade"><section class="sheet" role="dialog" aria-modal="true" aria-label="${esc(name)}"><div class="sheet-head"><h2>${esc(name)}</h2><button data-close aria-label="Close">${ic('close',19)}</button></div>${onSubmit?`<form id="entry-form">${content}<div class="buttonrow"><button type="submit" class="button primary block">${esc(submitText)}</button></div></form>`:content}</section></div>`;const backdrop=layer.querySelector('.shade');backdrop.onclick=e=>{if(e.target===backdrop)closeSheet()};layer.querySelector('[data-close]').onclick=closeSheet;if(onSubmit){layer.querySelector('form').onsubmit=async ev=>{ev.preventDefault();const form=ev.currentTarget,vals=Object.fromEntries(new FormData(form).entries());let outcome=await onSubmit(vals);if(outcome!==false){closeSheet();render()}}}}
