function render(reset=false){if(!data)return;setTheme();let old=reset?0:view.scrollTop;const inRoute=!!ui.route;header.innerHTML=`<div class="header-main"><div><div class="brand">HOE</div><div class="brand-desc">Heaven On Earth</div></div><div class="header-right"><div class="mode"><button class="${ui.mode==='life'?'on':''}" data-act="mode:life">Life</button><button class="${ui.mode==='money'?'on':''}" data-act="mode:money">Money</button></div><button class="icon-button" aria-label="Settings" data-act="route:settings">${ic('gear',21)}</button></div></div>`;
 let items=ui.mode==='life'?[['today','Today','home'],['matrix','Matrix','matrix'],['radar','Radar','radar'],['calendar','Calendar','calendar'],['notes','Notes','notes']]:[['overview','Overview','home'],['activity','Activity','list'],['add','Add','plus'],['commitments','Bills','calendar'],['accounts','Accounts','money']];
 let [rDone,rTotal]=radarStats(localDay());nav.innerHTML=items.map(([p,label,ico])=>`<button class="nav-tab ${!inRoute&&(ui.mode==='life'?ui.page:ui.moneyPage)===p?'active':''}" data-act="${p==='add'?'quick-money':`tab:${p}`}" aria-label="${label}">${p==='radar'?`<span class="radar-nav-ring" style="--percent:${rTotal?Math.round(rDone/rTotal*100):0}%"><b>${rDone}/${rTotal}</b></span>`:ic(ico,21)}<span>${label}</span></button>`).join('');
 if(ui.route!=='focus'&&clock){clearInterval(clock);clock=null}const content=ui.route?routeView():ui.mode==='life'?({today:todayView,matrix:matrixView,radar:radarView,calendar:calendarView,notes:notesView}[ui.page]||todayView)():({overview:moneyHome,activity:moneyActivity,commitments:moneyCommitments,accounts:moneyAccounts}[ui.moneyPage]||moneyHome)();view.innerHTML=content;view.scrollTop=old;if(reset)view.scrollTop=0;bindSpecial();}
function bindSpecial(){let search=$('#note-search');if(search)search.addEventListener('input',ev=>{ui.notesQuery=ev.target.value;const results=$('#notes-results');if(results)results.innerHTML=notesCards()});let noteTitle=$('#note-title'),noteBody=$('#note-body');if(noteTitle&&noteBody){let saveDelay;const saveNote=()=>{let n=data.notes.find(n=>n.id===ui.detail);if(!n)return;n.title=noteTitle.value;n.body=noteBody.value;n.updated=new Date().toISOString();clearTimeout(saveDelay);saveDelay=setTimeout(()=>persist().catch(()=>{}),450)};noteTitle.oninput=saveNote;noteBody.oninput=saveNote;noteTitle.onblur=()=>persist();noteBody.onblur=()=>persist();}if(ui.route==='focus')clockUpdater()}
