const autoLockCheck=()=>{if(!data)return;let mins=Number((data.settings.lockAfter||'1').split(' ')[0]);if(Number.isFinite(mins)&&mins>0&&Date.now()-lastActive>mins*60000)lock()};
document.addEventListener('visibilitychange',()=>{if(!document.hidden){autoLockCheck();if(data&&ui.route==='focus')clockUpdater()}else{lastActive=Date.now()}});
window.addEventListener('pagehide',()=>{if(data)persist()});
setInterval(()=>{if(!data)return;const time=$('#live-time');if(time)time.textContent=nowTime();if(ui.route==='focus')updateClockUI()},30000);
/* Life screens */
function activeTasks(){return data.tasks.filter(x=>!x.done&&!x.archived&&x.status!=='Archived')}
function priorityOf(t){let p=Number(t.priority);return p>=1&&p<=4?p:2}
function tasksForQuadrant(q){return activeTasks().filter(t=>priorityOf(t)===q).filter(t=>ui.matrixFilter==='All'||t.category===ui.matrixFilter).sort((a,b)=>(a.due||'9999-99-99').localeCompare(b.due||'9999-99-99'))}
function displayedEvents(date){let ev=[...data.events,...data.blocks.filter(b=>b.source==='event')].filter(x=>!x.archived);return ev.filter(x=>{if(x.date===date)return true;if(!x.date||!x.repeat||x.repeat==='none'||date<x.date)return false;let start=new Date(x.date+'T12:00:00'),d=new Date(date+'T12:00:00'),days=Math.round((d-start)/86400000);if(x.repeat==='daily')return true;if(x.repeat==='weekly')return days%7===0;if(x.repeat==='monthly')return start.getDate()===d.getDate();return false}).map(x=>({...x,kind:'event'})).sort((a,b)=>(a.time||'').localeCompare(b.time||''))}
function todaysBlocks(date){return data.blocks.filter(b=>!b.archived&&b.source!=='event'&&b.date===date).sort((a,b)=>(a.time||'').localeCompare(b.time||''))}
function currentDayStatus(){let time=minuteOf(nowTime()),date=localDay();let blocks=[...todaysBlocks(date).map(b=>({...b,kind:'block'})),...displayedEvents(date)].map(x=>({...x,start:minuteOf(x.time),end:minuteOf(x.time)+Number(x.duration||30)}));let ongoing=blocks.filter(x=>x.start<=time&&x.end>time).sort((a,b)=>a.kind==='block'?-1:1)[0];let next=blocks.filter(x=>x.start>time).sort((a,b)=>a.start-b.start)[0];return{ongoing,next,blocks}}
function radarComplete(entry,d=localDay()){const checks=data.radarDays[d]||{};if(checks[entry.id]===true)return true;if(checks[entry.id]===false)return false;const type=entry.type;const endDay=new Date(d+'T23:59:59').getTime();const startDay=new Date(d+'T00:00:00').getTime();if(type==='sleep')return sleepIntervals().some(x=>x.end>startDay&&x.end<=endDay+24*60*60000&&x.start<endDay&&x.start>startDay-24*60*60000&&x.end>=startDay);if(type==='weight')return data.weight.some(x=>x.date===d&&!x.archived);if(type==='face')return data.photos.some(x=>x.date===d&&!x.archived);if(type==='review'&&data.notes.some(n=>n.radarReviewDate===d&&!n.archived&&String(n.body||'').trim()))return true;if(type==='custom')return !!checks[entry.id];if(['water','read','exercise','review'].includes(type)){let total=data.dailyLogs.filter(x=>x.kind===type&&x.date===d&&!x.archived).reduce((v,x)=>v+(type==='review'?1:Number(x.value)||0),0);return total>=Number(entry.target||1)}return !!checks[entry.id]}
function radarStats(d=localDay()){let arr=data.radarItems.filter(x=>!x.disabled);return[arr.filter(x=>radarComplete(x,d)).length,arr.length]}
function todayView(){const now=new Date(),t=nowTime(),current=currentDayStatus(),focus=data.focusState,[done,total]=radarStats(),next=current.next,active=current.ongoing;let h=`<div class="eyebrow">${esc(dateText(localDay()))}</div><div class="big-clock" id="live-time">${esc(t)}</div><div class="section-sub" style="margin-top:8px">You are here.</div>`;
 if(focus){h+=`<div class="timeline-card"><div class="now-tag">In focus now</div><h2>${esc(focus.title||'Focus session')}</h2><div class="time">Started ${esc(new Date(focus.startedAt).toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'}))}</div>${button(`${ic('play',16)} Return to focus`,'route:focus',true,'block')}</div>`}
 else if(active){h+=`<div class="timeline-card"><div class="now-tag">Now · ${esc(active.kind==='event'?'Calendar event':'Time block')}</div><h2>${esc(active.title)}</h2><div class="time">${esc(active.time)} – ${esc(tPlus(active.time,Number(active.duration||30)))}</div><div class="buttonrow">${button(`${ic('play',16)} Start focus`,'focus-from:'+active.id,true)}${button('Details',`${active.kind==='event'?'event':'block'}:${active.id}`)}</div></div>`}
 else{h+=`<div class="timeline-card"><div class="now-tag">Nothing scheduled right now</div><h2>What are you doing?</h2><p class="section-sub">Give this part of the day a name. You can change it later.</p>${button(`${ic('plus',16)} Record a time block`,'new:block',true,'block')}</div>`}
 h+=sect('Next on your day','tab:calendar','Calendar');if(next){h+=`<button class="home-event" data-act="${next.kind==='event'?'event':'block'}:${next.id}"><span class="time-chip">${esc(next.time)}</span><span style="flex:1"><strong>${esc(next.title)}</strong><small>${next.kind==='event'?'Calendar event':'Planned activity'}</small></span>${ic('next',17)}</button>`}else h+=`<div class="rowlist">${row('No more events today','Add something to your calendar','new:event','', 'calendar')}</div>`;
 h+=`<button class="panel radar-mini" data-act="tab:radar">${donut(done,total)}<div style="flex:1;min-width:0"><strong style="display:block;font-size:15px">Daily essentials</strong><div class="subtle fine" style="margin:5px 0">${done} completed · ${total-done} remaining</div><div class="fine subtle">Tap to record sleep, weight, face and more.</div></div>${ic('next',17)}</button>`;
 const urgent=activeTasks().filter(x=>priorityOf(x)===1).slice(0,3);h+=sect('Do now','tab:matrix','Matrix');if(urgent.length){h+=`<div class="rowlist">${urgent.map(x=>taskRow(x)).join('')}</div>`}else h+=`<div class="empty">Your urgent-important quadrant is clear.</div>`;
 h+=`<div class="buttonrow">${button(`${ic('plus',16)} Quick capture`,'quick-capture',true)}${button(`${ic('clock',16)} Time lock`,'focus-picker')}</div>`;
 const pending=(data.inbox||[]).filter(x=>!x.archived);if(pending.length)h+=`<button class="row panel" style="margin-top:9px" data-act="route:inbox">${ic('inbox',18)}<span class="row-main">Inbox · ${pending.length} to sort</span>${ic('next',16)}</button>`;
 return h}
function taskRow(t){return `<div class="row"><button class="checkbutton" data-act="task-check:${t.id}" aria-label="Mark ${esc(t.title)} complete">${check(t.done)}</button><button class="row-main" data-act="task:${t.id}" style="text-align:left"><span class="row-title">${esc(t.title)}</span><span class="row-desc" style="display:block">${esc(t.category||'Personal')}${t.due?' · '+esc(dateText(t.due)):''}</span></button>${ic('next',16)}</div>`}
function matrixView(){let categories=['All',...data.categories];const headings=[['Do now','Urgent · Important'],['Schedule','Important · Not urgent'],['Delegate','Urgent · Less important'],['Remove','Neither urgent nor important']];let h=title('Matrix','One place for every task. Filter by area of life.','new:task','New task');h+=chips(categories,ui.matrixFilter,'matrix-filter');h+=`<div class="matrix-grid">`+headings.map(([name,desc],index)=>{let q=index+1,t=tasksForQuadrant(q);return `<section class="quadrant"><div class="quad-head"><strong>${name}</strong><span>${t.length}</span></div><div class="quad-desc">${desc}</div><div class="quad-items">${t.slice(0,4).map(x=>`<div class="quad-item"><button class="checkbutton" data-act="task-check:${x.id}" aria-label="Complete ${esc(x.title)}">${check(false)}</button><button data-act="task:${x.id}">${esc(x.title)}</button></div>`).join('')}${t.length>4?`<button class="fine subtle" data-act="quadrant:${q}">+ ${t.length-4} more</button>`:''}</div><div class="quad-foot"><button data-act="quadrant:${q}">View all</button><button aria-label="Add task to ${name}" data-act="new:task:${q}">${ic('plus',17)}</button></div></section>`}).join('')+`</div>`;
 h+=`<div class="buttonrow">${button(`${ic('plus',17)} Add task`,'new:task',true)}${button(`${ic('inbox',17)} Inbox`,'route:inbox')}</div>`;return h}
function quadrantView(){const q=Number(ui.detail)||1,head=['','Do now','Schedule','Delegate','Remove'][q],items=tasksForQuadrant(q);return backLink('Matrix')+title(head,`${items.length} open tasks`,'new:task:'+q,'New task')+`<div class="rowlist">${items.map(taskRow).join('')||'<div class="empty">No tasks here.</div>'}</div>`}
function taskDetail(){const t=data.tasks.find(x=>x.id===ui.detail);if(!t)return backLink()+`<div class="empty">Task not found</div>`;return backLink('Matrix')+title(t.title)+`<div class="task-detail-attrs"><span class="tag">${esc(t.category||'Personal')}</span><span class="tag">${esc(['','Do now','Schedule','Delegate','Remove'][priorityOf(t)])}</span>${t.due?`<span class="tag">Due ${esc(dateText(t.due))}</span>`:''}</div>${t.details?`<div class="panel" style="white-space:pre-wrap;line-height:1.6">${esc(t.details)}</div>`:''}${t.smallest?`<div class="panel"><div class="mini">First action</div><div style="margin-top:7px">${esc(t.smallest)}</div></div>`:''}<div class="buttonrow">${button(`${ic('play',16)} Start focus`,'focus-task:'+t.id,true)}${button(`${ic('edit',16)} Edit`,'edit:task:'+t.id)}</div>${button(t.done?'Mark incomplete':'Mark complete','task-check:'+t.id,false,'block')}${button('Archive task','archive:tasks:'+t.id,false,'block danger')}`}
function inboxView(){const pending=(data.inbox||[]).filter(x=>!x.archived);let h=backLink('Today')+title('Inbox','Thoughts you captured without stopping to organise them.','quick-capture','Capture');h+=pending.length?`<div class="rowlist">${pending.map(x=>`<div class="row"><span class="row-main"><span class="row-title">${esc(x.text||x.title||'Untitled')}</span></span><button class="button" style="padding:8px;min-height:36px" data-act="inbox-to-task:${x.id}">Task</button><button aria-label="Archive" data-act="archive:inbox:${x.id}">${ic('archive',17)}</button></div>`).join('')}</div>`:'<div class="empty">Inbox is clear.</div>';return h}
function radarView(){ui.radarDate=ui.radarDate||localDay();const active=data.radarItems.filter(x=>!x.disabled),[done,total]=radarStats(ui.radarDate),isToday=ui.radarDate===localDay();let h=title('Daily Radar','Your essentials, not another list of tasks.');h+=`<div class="month-nav"><button data-act="radar-date:-1">${ic('back')}</button><strong>${esc(dateText(ui.radarDate,{weekday:'long',day:'numeric',month:'long'}))}</strong><button data-act="radar-date:1">${ic('next')}</button></div>${donut(done,total,true)}<div class="rowlist">`;
 h+=active.map(x=>{let complete=radarComplete(x,ui.radarDate),sub=radarSub(x,ui.radarDate);return `<button type="button" class="row" data-act="radar-log:${x.id}" aria-label="${esc(x.label)}"><span class="checkbutton">${check(complete)}</span><span class="row-main"><span class="row-title">${esc(x.label)}</span><span class="row-desc" style="display:block">${esc(sub)}</span></span>${ic('next',17)}</button>`}).join('')+'</div>';
 h+=`<div class="buttonrow">${button('Edit daily items','route:radar-settings')}${button('Review entries','route:daily-records')}</div>`;if(!isToday)h+=`<p class="fine subtle">Viewing another day. Daily entries are recorded against the selected date.</p>`;return h}
function logAmount(kind,d){return data.dailyLogs.filter(x=>x.kind===kind&&x.date===d&&!x.archived).reduce((sum,x)=>sum+Number(x.value||0),0)}
function radarSub(item,d){if(item.type==='weight'){let x=data.weight.filter(x=>x.date===d&&!x.archived).at(-1);return x?`${Number(x.kg||x.value||0).toFixed(1)} kg`:'Record weight'}if(item.type==='sleep'){let total=sleepDuration(d);return total?`${Math.floor(total/60)} h ${String(total%60).padStart(2,'0')} min logged`:'View sleep grid'}if(item.type==='face')return data.photos.some(x=>x.date===d&&!x.archived)?'Photograph recorded':'Daily photograph';if(item.type==='water')return `${(logAmount('water',d)/1000).toFixed(2)} / ${(Number(item.target||2000)/1000).toFixed(1)} L`;if(item.unit==='min')return `${logAmount(item.type,d)} / ${Number(item.target||20)} minutes`;if(item.type==='review')return data.dailyLogs.some(x=>x.kind==='review'&&x.date===d)?'Review recorded':'One short note';return 'Tap to mark or record'}
function radarSettings(){let h=backLink('Radar')+title('Daily essentials','Seven is a starting point. Keep only what you actually want to record.');h+=`<div class="rowlist">${data.radarItems.map(x=>`<div class="row"><span class="row-main"><span class="row-title">${esc(x.label)}</span><span class="row-desc" style="display:block">${esc(x.type==='custom'?'Custom check':x.type)}${x.unit?' · '+x.target+' '+x.unit:''}</span></span><button class="button" style="min-height:36px;padding:7px" data-act="radar-config:${x.id}">Edit</button><button class="checkbutton" aria-label="Toggle visibility" data-act="radar-enable:${x.id}">${check(!x.disabled)}</button></div>`).join('')}</div>${button(`${ic('plus',17)} Add essential`,'new:radar-item',true,'block')}<p class="fine subtle" style="margin-top:13px">Sleep, weight and photos can complete their items automatically. No streak penalties or reminders unless you choose them.</p>`;return h}
function safeImage(value){return typeof value==='string'&&/^data:image\/(?:jpeg|jpg|png|webp);base64,[a-zA-Z0-9+/=]+$/.test(value)?value:''}
function dailyRecordsView(){const date=ui.radarDate||localDay(),records=data.dailyLogs.filter(x=>x.date===date&&!x.archived).sort((a,b)=>(b.at||'').localeCompare(a.at||''));return backLink('Radar')+title('Recorded today',dateText(date))+`<div class="rowlist">${records.map(x=>`<div class="row"><span class="row-main"><span class="row-title">${esc(x.kind)} · ${esc(x.value||'')}</span><span class="row-desc" style="display:block">${esc(x.note||'Recorded')}</span></span><button class="button danger" type="button" data-act="archive:dailyLogs:${esc(x.id)}" style="min-height:32px;padding:7px">Undo</button></div>`).join('')||'<div class="empty">No additional records on this day.</div>'}</div><p class="fine subtle">Sleep, weight and photographs are managed on their own screens.</p>`}
function sleepIntervals(){let arr=[];for(let x of data.sleep){if(x.archived)continue;let start,end;if(x.startAt&&x.endAt){start=new Date(x.startAt).getTime();end=new Date(x.endAt).getTime()}else if(x.date&&x.start&&x.end){start=new Date(x.date+'T'+x.start).getTime();end=new Date(x.date+'T'+x.end).getTime();if(end<=start)end+=86400000}else if(x.date&&Number(x.hours)>0){end=new Date(x.date+'T08:00:00').getTime();start=end-Number(x.hours)*3600000}else continue;if(!Number.isFinite(start)||!Number.isFinite(end)||end<=start||end-start>36*3600000)continue;arr.push({id:x.id,start,end,type:x.type||'Main sleep',estimated:!!x.approximate})}return arr}
function sleepDuration(d){let start=new Date(d+'T00:00:00').getTime(),end=new Date(d+'T24:00:00').getTime();return Math.round(sleepIntervals().reduce((v,x)=>v+Math.max(0,Math.min(x.end,end)-Math.max(x.start,start)),0)/60000)}
function sleepView(){let week=addDays(weekStart(localDay()),ui.sleepWeek*7),days=Array.from({length:7},(_,i)=>addDays(week,i)),chosen=ui.sleepSelected||localDay(),intervals=sleepIntervals();let h=backLink('Radar')+title('Sleep','The full day, not only a nightly total.');h+=`<div class="month-nav"><button data-act="sleep-week:-1">${ic('back')}</button><strong>${esc(dateText(days[0],{day:'numeric',month:'short'}))} – ${esc(dateText(days[6],{day:'numeric',month:'short'}))}</strong><button data-act="sleep-week:1">${ic('next')}</button></div><div class="sleep-shell"><div class="sleep-axis"><div></div><div><span>00</span><span>06</span><span>12</span><span>18</span><span>24</span></div></div>`;
 h+=days.map(d=>{let start=new Date(d+'T00:00:00').getTime(),end=start+86400000;let bars=intervals.filter(x=>x.end>start&&x.start<end).map(x=>{let left=Math.max(0,x.start-start)/86400000*100,right=Math.min(end,x.end)-start,width=right/86400000*100-left;return `<i class="sleep-segment ${x.type.toLowerCase().includes('nap')?'nap':''}" style="left:${left.toFixed(3)}%;width:${Math.max(.25,width).toFixed(3)}%" title="${esc(x.type)}"></i>`}).join('');return `<button class="sleep-row ${d===chosen?'selected':''}" data-act="sleep-day:${d}"><small>${esc(dateText(d,{weekday:'short',day:'numeric'}))}</small><span class="sleep-track">${bars}</span></button>`}).join('')+`</div><div class="sleep-legend"><span><i></i>Main sleep</span><span><i class="nap"></i>Nap</span></div>`;
 const total=sleepDuration(chosen);h+=`<div class="panel"><div class="mini">${esc(dateText(chosen))}</div><div style="font-size:25px;font-weight:700;margin:8px 0">${Math.floor(total/60)} h ${String(total%60).padStart(2,'0')} min</div><div class="fine subtle">Includes portions of overnight sleep that fall on this calendar day.</div></div>${sect('Sleep entries')}`;
 const dayEntries=intervals.filter(x=>x.end>new Date(chosen+'T00:00').getTime()&&x.start<new Date(chosen+'T24:00').getTime());h+=`<div class="rowlist">${dayEntries.map(x=>row(x.type,new Date(x.start).toLocaleString('en-ZA',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'})+' – '+new Date(x.end).toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'}),'sleep-edit:'+x.id,'', 'bed')).join('')||'<div class="empty">No sleep recorded.</div>'}</div>${button(`${ic('plus',16)} Add sleep`,'new:sleep',true,'block')}`;return h}
function weightView(){let entries=[...data.weight].filter(x=>!x.archived).sort((a,b)=>(b.date||'').localeCompare(a.date||'')),latest=entries[0];let h=backLink('Radar')+title('Weight','Your own measurements, without targets or judgement.');h+=`<div class="panel"><div class="mini">Latest recorded</div><div class="money-total">${latest?Number(latest.kg||latest.value).toFixed(1)+' kg':'—'}</div>${latest?`<p class="fine subtle">${esc(dateText(latest.date))}</p>`:''}${weightChart(entries)}</div>${sect('Recent entries')}<div class="rowlist">${entries.slice(0,30).map(x=>row(dateText(x.date),x.note||'Recorded','weight-edit:'+x.id,Number(x.kg||x.value).toFixed(1)+' kg','weight')).join('')||'<div class="empty">No weight entries yet.</div>'}</div>${button('Record weight','new:weight',true,'block')}`;return h}
function weightChart(arr){const points=arr.filter(x=>Number.isFinite(Number(x.kg||x.value))&&x.date).slice(0,12).reverse();if(points.length<2)return '<p class="fine subtle">A trend appears after two records.</p>';let values=points.map(x=>Number(x.kg||x.value)),lo=Math.min(...values)-.4,hi=Math.max(...values)+.4,dx=260/Math.max(1,points.length-1),path=values.map((v,i)=>`${i===0?'M':'L'} ${15+i*dx} ${70-(v-lo)/(hi-lo)*60}`).join(' ');return `<svg viewBox="0 0 290 83" role="img" aria-label="Weight trend over ${points.length} entries" style="width:100%;height:100px;margin-top:7px"><path d="M15 20H275M15 50H275M15 78H275" stroke="var(--line)" fill="none"/><path d="${path}" stroke="var(--ink)" stroke-width="2.2" fill="none"/>${values.map((v,i)=>`<circle cx="${15+i*dx}" cy="${70-(v-lo)/(hi-lo)*60}" r="3.2" fill="var(--ink)"/>`).join('')}</svg>`}
function faceView(){const photos=data.photos.filter(x=>!x.archived).sort((a,b)=>(b.date||'').localeCompare(a.date||''));let h=backLink('Radar')+title('Daily photograph','One private image when you choose to record it.');h+=`<div class="notes-grid">${photos.map(p=>`<button class="note-tile" data-act="photo:${p.id}" style="padding:7px;min-height:155px">${safeImage(p.dataUrl)?`<img style="width:100%;height:125px;object-fit:cover;border-radius:8px" src="${safeImage(p.dataUrl)}" alt="Photo recorded ${esc(p.date)}">`:ic('camera',40)}<small style="margin:8px">${esc(dateText(p.date))}</small></button>`).join('')}</div>${button(`${ic('camera',17)} Take or choose photo`,'new:photo',true,'block')}<p class="fine subtle" style="margin-top:12px">Photos are compressed and encrypted inside this device's vault. They are not uploaded to Google Drive or YouTube automatically.</p>`;return h}
/* Calendar · Events are primary. Time blocks are visible on Today, and optional in Day view. */
function eventsOn(date){return displayedEvents(date)}
function calendarView(){const d=ui.date||localDay(),mode=ui.calendarView,month=ui.month||d.slice(0,7);let h=title('Calendar','Events, appointments and meetings.','new:event','Add event');h+=segment([['month','Month'],['week','Week'],['day','Day']],mode,'calendar-view');
 if(mode==='month'){const first=month+'-01',f=new Date(first+'T12:00'),startOffset=(f.getDay()+6)%7,last=new Date(f.getFullYear(),f.getMonth()+1,0).getDate();h+=`<div class="month-nav"><button data-act="calendar-month:-1">${ic('back')}</button><strong>${esc(f.toLocaleDateString('en-ZA',{month:'long',year:'numeric'}))}</strong><button data-act="calendar-month:1">${ic('next')}</button></div><div class="days-grid">${['M','T','W','T','F','S','S'].map(x=>`<div class="weekday-label">${x}</div>`).join('')}${Array(startOffset).fill('<div></div>').join('')}${Array.from({length:last},(_,i)=>{let x=`${month}-${String(i+1).padStart(2,'0')}`,has=eventsOn(x).length;return `<button class="day-cell ${d===x?'selected':''} ${x===localDay()?'today':''}" data-act="calendar-date:${x}">${i+1}${has?'<i class="day-dot"></i>':'<i style="height:4px"></i>'}</button>`}).join('')}</div>`}
 if(mode==='week'){let first=weekStart(d),days=Array.from({length:7},(_,i)=>addDays(first,i));h+=`<div class="month-nav"><button data-act="calendar-week:-1">${ic('back')}</button><strong>${esc(dateText(days[0],{month:'short',day:'numeric'}))} – ${esc(dateText(days[6],{month:'short',day:'numeric',year:'numeric'}))}</strong><button data-act="calendar-week:1">${ic('next')}</button></div><div class="week-strip">${days.map(x=>`<button class="week-day ${x===d?'selected':''}" data-act="calendar-date:${x}"><small>${esc(dateText(x,{weekday:'short'}))}</small><strong>${Number(x.slice(-2))}</strong>${eventsOn(x).length?'<span class="day-dot"></span>':'<span style="height:4px"></span>'}</button>`).join('')}</div>`}
 if(mode==='day')h+=`<div class="month-nav"><button data-act="calendar-date:${addDays(d,-1)}">${ic('back')}</button><strong>${esc(dateText(d,{weekday:'long',month:'long',day:'numeric'}))}</strong><button data-act="calendar-date:${addDays(d,1)}">${ic('next')}</button></div>`;
 h+=`<div class="agenda-date">${esc(dateText(d,{weekday:'long',month:'long',day:'numeric'}))} · ${eventsOn(d).length} event${eventsOn(d).length===1?'':'s'}</div>`;let events=eventsOn(d);if(events.length)h+=events.map(x=>`<button class="agenda-event" data-act="event:${x.id}"><span class="agenda-time">${esc(x.time||'All day')}</span><span class="detail"><b>${esc(x.title)}</b><small>${x.location?esc(x.location)+' · ':''}${x.time?esc(tPlus(x.time,Number(x.duration||30))):''}${x.repeat&&x.repeat!=='none'?' · Recurring':''}</small></span>${ic('next',16)}</button>`).join('');else h+=`<div class="empty">No events on this day.</div>`;
 h+=button(`${ic('plus',16)} Add event`,'new:event',true,'block');
 if(mode==='day'){let other=todaysBlocks(d);if(other.length)h+=sect('Recorded time blocks')+`<div class="rowlist">${other.map(x=>row(x.title,`${x.time||'—'} · ${x.duration||30} min`,'block:'+x.id,'', 'clock')).join('')}</div>`;}
 h+=`<p class="fine subtle" style="margin-top:16px">Google Calendar is not connected to this app. Events entered here are saved to your encrypted HOE vault only.</p>`;return h}
function eventDetail(){let ev=[...data.events,...data.blocks].find(x=>x.id===ui.detail);if(!ev)return backLink('Calendar')+'<div class="empty">Event not found.</div>';return backLink('Calendar')+title(ev.title)+`<div class="rowlist">${row('Date',dateText(ev.date),'','', 'calendar')}${row('Time',`${ev.time||'09:00'} – ${tPlus(ev.time||'09:00',Number(ev.duration||30))}`,'','', 'clock')}${ev.location?row('Location',ev.location,'','', 'home'):''}${ev.repeat&&ev.repeat!=='none'?row('Repeats',ev.repeat):''}</div>${ev.notes?`<div class="panel" style="white-space:pre-wrap">${esc(ev.notes)}</div>`:''}<div class="buttonrow">${button('Edit','edit:event:'+ev.id,true)}${button('Start focus','focus-from:'+ev.id)}</div>${button('Archive event','archive:'+(data.events.some(x=>x.id===ev.id)?'events':'blocks')+':'+ev.id,false,'block danger')}`}
