/* Notes are plain. A grid, then a separate full-screen editor that auto-saves. */
function notesCards(){let list=[...data.notes].filter(n=>!n.archived&&(n.title+' '+(n.body||'')).toLowerCase().includes(ui.notesQuery.toLowerCase())).sort((a,b)=>Number(!!b.pinned)-Number(!!a.pinned)||(b.updated||b.created||'').localeCompare(a.updated||a.created||''));return `<div class="notes-grid"><button class="note-tile new-note" data-act="new-note">${ic('plus',30)}<b>New note</b></button>${list.map(x=>`<button class="note-tile" data-act="note:${x.id}"><b>${x.pinned?'⌑ ':''}${esc(x.title||'Untitled')}</b><p>${esc(x.body||'Empty note')}</p><small>${esc(dateText((x.updated||x.created||localDay()).slice(0,10),{day:'numeric',month:'short'}))}</small></button>`).join('')}</div>`}
function notesView(){return title('Notes','A simple place to write. No separate journal.')+`<label class="input" style="display:flex;gap:10px;align-items:center">${ic('search',19)}<input id="note-search" type="search" aria-label="Search notes" style="width:100%;border:0;background:none;min-width:0" placeholder="Search notes" value="${esc(ui.notesQuery)}"></label><div id="notes-results">${notesCards()}</div>`}
function noteEditor(){const n=data.notes.find(x=>x.id===ui.detail);if(!n)return backLink('Notes')+'<div class="empty">Note not found.</div>';return `<div class="note-editor"><div class="note-editor-top"><button class="button flat" data-act="back">${ic('back',18)} Notes</button><div style="display:flex;gap:3px"><button class="icon-button" data-act="note-pin:${n.id}" title="Pin note" aria-label="Pin note">${ic('pin',18)}</button><button class="icon-button" data-act="note-attach:${n.id}" title="Add image" aria-label="Attach image">${ic('image',18)}</button><button class="icon-button" data-act="note-options:${n.id}" title="Note options" aria-label="Note options">${ic('more',20)}</button></div></div><input class="note-title" id="note-title" aria-label="Note title" placeholder="Title" value="${esc(n.title||'')}" autocomplete="off"><textarea class="note-body" id="note-body" aria-label="Note content" placeholder="Start writing…" spellcheck="true">${esc(n.body||'')}</textarea>${(n.attachments||[]).map((a,i)=>`<button data-act="note-photo-detail:${n.id}:${i}"><img src="${safeImage(a.dataUrl)}" alt="Note attachment" class="note-attachment"></button>`).join('')}<p class="fine subtle">Saves automatically on this device.</p></div>`}
/* Focus / Time Lock. In-app timer cannot prevent switching to other iOS apps. */
function focusElapsedSeconds(){let f=data.focusState;if(!f)return 0;let end=f.paused?Number(f.pauseAt)||Date.now():Date.now();return Math.max(0,Math.floor((end-new Date(f.startedAt).getTime()-Number(f.pausedMs||0))/1000))}
function displayClock(sec){return `${String(Math.floor(sec/60)).padStart(2,'0')}:${String(sec%60).padStart(2,'0')}`}
function focusView(){const f=data.focusState;if(!f)return backLink('Today')+title('Focus')+'<div class="empty">No active session</div>'+button('Start focus','focus-picker',true,'block');const sec=focusElapsedSeconds(),target=Number(f.plannedMinutes||25)*60,percent=Math.min(100,Math.round(sec/target*100));return backLink('Today')+`<div style="text-align:center;margin-top:20px"><div class="mini">TIME LOCK</div><h1 style="margin-top:12px">${esc(f.title||'Focus')}</h1><div class="donut large" style="--percent:${percent}%"><div class="donut-inner"><b id="focus-clock" style="font-size:32px">${displayClock(sec)}</b><small>${f.paused?'Paused':'Time elapsed'}</small></div></div><p class="subtle fine">${f.plannedMinutes} minute intention · There is no penalty for taking longer.</p></div><div class="buttonrow">${button(f.paused?`${ic('play',16)} Resume`:`${ic('pause',16)} Pause`,'focus-pause')}${button(`${ic('check',16)} Finish`,'focus-finish',true)}</div><div class="panel"><h3>Where was I?</h3><p class="fine subtle">Leave one sentence to make returning easier.</p><textarea id="focus-return" class="input" rows="3" placeholder="Return note (optional)">${esc(f.returnNote||'')}</textarea>${button('Save return note','focus-note',false,'block')}</div><div class="buttonrow">${button('Capture interruption','focus-interruption')}${button('+ 15 minutes','focus-add15')}</div><p class="fine subtle">Time Lock protects your place inside HOE. A website cannot block other iPhone apps.</p>`}
function updateClockUI(){const el=$('#focus-clock');if(el&&data?.focusState)el.textContent=displayClock(focusElapsedSeconds())}
function clockUpdater(){clearInterval(clock);clock=setInterval(updateClockUI,950)}
function sessionHistory(){return backLink('Today')+title('Focus history','Actual recorded sessions, not planned time.')+`<div class="rowlist">${[...data.sessions].filter(x=>!x.archived).reverse().map(x=>row(x.title,`${esc(x.returnNote||'')} · ${dateText(x.date)}`,'session:'+x.id,`${Number(x.minutes)||0} min`,'clock')).join('')||'<div class="empty">No focus sessions recorded.</div>'}</div>`}
function sessionDetail(){let x=data.sessions.find(x=>x.id===ui.detail);return backLink('Focus history')+(x?title(x.title)+`<div class="panel"><p>${esc(x.minutes)} minutes · ${esc(dateText(x.date))}</p><p style="white-space:pre-wrap">${esc(x.returnNote||'No return note')}</p></div>`:'<div class="empty">Not found</div>')}
/* Money: separate mode, manually recorded; no bank access or cloud connection */
function activeTx(){return data.transactions.filter(x=>!x.archived)}
function txCounts(){let inSum=0,outSum=0,expected=0;for(let t of activeTx()){let val=Number(t.amount)||0;if(t.type==='In'){if(t.status==='Expected')expected+=val;else inSum+=val}else if(t.type==='Out'&&t.status!=='Planned')outSum+=val}let opening=data.accounts.filter(a=>!a.archived).reduce((v,a)=>v+Number(a.opening||0),0),committed=data.commitments.filter(x=>!x.archived&&x.status!=='Paid'&&x.status!=='Cancelled').reduce((v,a)=>v+(Number(a.amount)||0),0);return{opening,inSum,outSum,expected,committed,balance:opening+inSum-outSum}}
function accountBalance(acc){let result=Number(acc.opening||0);for(let t of activeTx()){if(t.status==='Expected'||t.status==='Planned')continue;let value=Number(t.amount)||0;if(t.type==='In'&&(t.accountId===acc.id||t.account===acc.name))result+=value;if(t.type==='Out'&&(t.accountId===acc.id||t.account===acc.name))result-=value;if(t.type==='Transfer'){if(t.fromAccount===acc.id)result-=value;if(t.toAccount===acc.id)result+=value}}return result}
function moneyHome(){let t=txCounts();let upcoming=data.commitments.filter(x=>!x.archived&&x.status!=='Paid'&&x.status!=='Cancelled').sort((a,b)=>(a.due||'9999').localeCompare(b.due||'9999')).slice(0,4);return title('Money','Your recorded finances, in rand.')+`<div class="panel panel-strong"><div class="mini">Recorded balance</div><div class="money-total">${formatR(t.balance)}</div><p class="fine subtle">Based only on amounts you have entered. Not a live bank balance.</p><hr class="rule"><div class="fin-line"><span>Income received</span><b>${formatR(t.inSum)}</b></div><div class="fin-line"><span>Money spent</span><b>${formatR(t.outSum)}</b></div><div class="fin-line"><span>Unpaid commitments</span><b>${formatR(t.committed)}</b></div><div class="fin-line"><span>Remaining after commitments</span><b>${formatR(t.balance-t.committed)}</b></div><div class="fin-line"><span>Expected income (not included)</span><b>${formatR(t.expected)}</b></div></div><div class="buttonrow">${button('− Money out','new:expense',true)}${button('+ Money in','new:income',true)}</div>${sect('Upcoming commitments','tab:commitments','See all')}<div class="rowlist">${upcoming.map(x=>row(x.name,`Due ${dateText(x.due)} · ${x.type}`,'commitment:'+x.id,formatR(x.amount),'calendar')).join('')||'<div class="empty">Nothing upcoming.</div>'}</div>${sect('Recent activity','tab:activity')}<div class="rowlist">${activeTx().slice(-4).reverse().map(txRow).join('')||'<div class="empty">No recorded transactions.</div>'}</div>`}
function txRow(x){return row(x.title||x.category||'Transaction',`${x.category||'Other'} · ${dateText(x.date)}`,'transaction:'+x.id,`${x.type==='Out'?'−':x.type==='In'?'+':'↔'} ${formatR(x.amount)}`,'money')}
function moneyActivity(){let cats=['All','In','Out','Transfer'];let arr=activeTx().filter(x=>ui.moneyFilter==='All'||x.type===ui.moneyFilter).sort((a,b)=>(b.date||'').localeCompare(a.date||''));return title('Activity','Money in, out and between accounts.','quick-money','Add')+chips(cats,ui.moneyFilter,'money-filter')+`<div class="rowlist">${arr.map(txRow).join('')||'<div class="empty">No transactions here.</div>'}</div><div class="buttonrow">${button('Money out','new:expense',true)}${button('Money in','new:income',true)}</div>${button('Transfer between accounts','new:transfer',false,'block')}`}
function moneyCommitments(){const bill=data.commitments.filter(x=>!x.archived).sort((a,b)=>(a.due||'').localeCompare(b.due||'')),debts=data.debts.filter(x=>!x.archived);return title('Commitments','Keep track of what is due, not automatically deducted.','new:commitment','Add bill')+`<div class="rowlist">${bill.map(x=>row(x.name,`${x.type||'Bill'} · ${dateText(x.due)} · ${x.status||'Expected'}`,'commitment:'+x.id,formatR(x.amount),'calendar')).join('')||'<div class="empty">No bills or subscriptions yet.</div>'}</div><div class="buttonrow">${button('Add bill','new:commitment',true)}${button('Add debt','new:debt')}</div>${sect('Debts')}<div class="rowlist">${debts.map(x=>row(x.name,`${x.side||'I owe'} · ${dateText(x.due)}`,'debt:'+x.id,formatR(Math.max(0,Number(x.amount||0)-Number(x.paid||0))),'money')).join('')||'<div class="empty">No debts recorded.</div>'}</div><p class="fine subtle">Bills and debts are commitments. Marking one paid does not silently create a bank transaction.</p>`}
function moneyAccounts(){let a=data.accounts.filter(x=>!x.archived);return title('Accounts','Manual accounts. No bank connection.','new:account','New account')+`<div class="rowlist">${a.map(x=>row(x.name,'Opening balance: '+formatR(x.opening||0),'account:'+x.id,formatR(accountBalance(x)),'money')).join('')||'<div class="empty">Add your bank account, cash or wallet to track a recorded balance.</div>'}</div>${button('Add account','new:account',true,'block')}`}
function moneyDetail(kind){let table={transaction:'transactions',commitment:'commitments',account:'accounts',debt:'debts'}[kind],x=data[table]?.find(x=>x.id===ui.detail);if(!x)return backLink('Money')+'<div class="empty">Entry not found</div>';let label=x.name||x.title;let details=kind==='transaction'?`<div class="rowlist">${row('Amount',formatR(x.amount))}${row('Type',x.type)}${row('Status',x.status||'Recorded')}${row('Category',x.category||'Other')}${row('Date',dateText(x.date))}</div>`:kind==='account'?`<div class="panel"><div class="mini">Recorded balance</div><div class="money-total">${formatR(accountBalance(x))}</div></div>`:kind==='debt'?`<div class="rowlist">${row('Original amount',formatR(x.amount))}${row('Paid',formatR(x.paid))}${row('Remaining',formatR(Number(x.amount||0)-Number(x.paid||0)))}</div>`:`<div class="rowlist">${row('Amount',formatR(x.amount))}${row('Due',dateText(x.due))}${row('Type',x.type)}${row('Status',x.status||'Expected')}</div>`;
 return backLink('Money')+title(label)+details+`<div class="buttonrow">${button('Edit','edit:'+kind+':'+x.id,true)}${kind==='commitment'?button(x.status==='Paid'?'Mark unpaid':'Mark paid','commitment-paid:'+x.id):''}${kind==='debt'?button('Record repayment','debt-repay:'+x.id):''}</div>${button('Archive','archive:'+table+':'+x.id,false,'block danger')}`}
/* Settings, backup, recoverability */
function settingsView(){let minutes=data.settings.lockAfter||'1 minute';return backLink('Today')+title('Settings','Customize without adding extra pages.')+`<div class="rowlist">${row('Categories','Filters for the Matrix','route:categories','', 'matrix')}${row('Daily Radar','Edit your essentials','route:radar-settings','', 'radar')}${row('Appearance',data.settings.theme==='light'?'Light':'Dark','settings:theme','', 'moon')}${row('Privacy lock',minutes,'settings:lock','', 'lock')}${row('Change passphrase','Re-encrypt this vault','settings:passphrase','', 'shield')}${row('Backup & restore','Your encrypted records','route:backup','', 'cloud')}${row('Focus history','Recorded time and return notes','route:sessions','', 'clock')}${row('Archive & history','Archived records','route:archive','', 'archive')}</div><div class="panel"><div class="mini">Connections</div><div class="fin-line"><span>Google Drive</span><b class="subtle">Not connected</b></div><div class="fin-line"><span>Google Calendar</span><b class="subtle">Not connected</b></div><p class="fine subtle" style="margin-top:13px">The Google services connected to ChatGPT are not automatically connected to HOE. Drive sync requires a separate, securely configured Google OAuth integration.</p></div>${button('Lock HOE now','lock',false,'block')}`}
