function archiveView(){const archived=[...data.tasks.map(x=>({...x,table:'tasks',label:x.title})),...data.notes.map(x=>({...x,table:'notes',label:x.title||'Untitled'})),...data.events.map(x=>({...x,table:'events',label:x.title})),...data.blocks.map(x=>({...x,table:'blocks',label:x.title})),...data.transactions.map(x=>({...x,table:'transactions',label:x.title})),...data.photos.map(x=>({...x,table:'photos',label:'Daily photo '+(x.date||'')})),...data.sleep.map(x=>({...x,table:'sleep',label:'Sleep '+(x.date||'')})),...data.weight.map(x=>({...x,table:'weight',label:'Weight '+(x.date||'')}))].filter(x=>x.archived);return backLink('Settings')+title('Archive','Completed and archived things stay recoverable.')+`<div class="rowlist">${archived.map(x=>row(x.label,x.table,'restore:'+x.table+':'+x.id,'','archive')).join('')||'<div class="empty">Your archive is empty.</div>'}</div>${sect('Recent history')}<div class="rowlist">${data.history.slice(0,35).map(x=>row(x.action,new Date(x.date).toLocaleString('en-ZA'))).join('')||'<div class="empty">No activity recorded.</div>'}</div>`}
function backupView(){return backLink('Settings')+title('Your data','Local encryption, optional manual backups.')+`<div class="panel"><div class="mini">Storage</div><div class="fin-line"><span>Saved</span><b>On this device</b></div><div class="fin-line"><span>Encryption</span><b>AES-256-GCM</b></div><div class="fin-line"><span>Google Drive sync</span><b>Not connected</b></div><div class="fin-line"><span>Last encrypted save</span><b>${stored?.updated?esc(new Date(stored.updated).toLocaleString('en-ZA')):'Not yet'}</b></div></div>${sect('Back up & recover')}<div class="rowlist">${row('Download encrypted backup','Recommended before any major update','backup-download','', 'download')}${row('Restore encrypted backup','Requires the backup passphrase','backup-restore','', 'upload')}${row('Export readable notes','TXT file — not encrypted','export-notes','', 'notes')}${row('Export readable tasks','CSV file — not encrypted','export-tasks','', 'list')}</div><div class="panel"><h3>Where are my records?</h3><p class="fine subtle">Inside the encrypted IndexedDB vault in this iPhone web app or browser. GitHub hosts only the app code. Clearing website data, removing the installed app, or changing browser storage can permanently delete the vault.</p><p class="fine subtle">Save the encrypted backup in your private Drive yourself. Keep the passphrase safely: there is no password reset service.</p></div>`}
