/* Form creation / edits */
function findRecord(table,recordId){return data[table]?.find(x=>String(x.id)===String(recordId))}
function taskForm(record,quadrant=1){let x=record||{},cat=x.category|| (ui.matrixFilter!=='All'?ui.matrixFilter:data.categories[0]);sheet(record?'Edit task':'New task',field('title','What needs doing?',x.title||'','text',true)+select('priority','Eisenhower quadrant',[[1,'Do now — urgent and important'],[2,'Schedule — important, not urgent'],[3,'Delegate — urgent, less important'],[4,'Remove — neither']],x.priority||quadrant)+select('category','Category',data.categories,cat)+field('due','Due date (optional)',x.due||'','date')+field('smallest','Smallest next action (optional)',x.smallest||'')+area('details','Notes (optional)',x.details||''),async v=>{if(!v.title?.trim())return false;let updated={...x,id:x.id||id(),title:v.title.trim(),priority:Number(v.priority),category:v.category,due:v.due,smallest:v.smallest,details:v.details,done:!!x.done};upsert('tasks',updated);if(updated._inboxSource){const item=findRecord('inbox',updated._inboxSource);if(item)item.archived=true;delete updated._inboxSource}await commit(record?.title?'Edited task':'Added task')})}
